pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    match bytes {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        value if value.starts_with("v:2:hello:") => {
            Ok(Msg::Hello(value["v:2:hello:".len()..].into()))
        }
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "v1:ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{value}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let message = Msg::Hello("desktop:client".into());
        let encoded = encode(&message);
        assert_eq!(encoded, "v:2:hello:desktop:client");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "desktop:client"));
    }
}

